CREATE TABLE IF NOT EXISTS organizations (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS entities (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), parent_id TEXT REFERENCES entities(id), name TEXT NOT NULL, sector TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS policy_versions (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), version INTEGER NOT NULL, name TEXT NOT NULL, thresholds JSONB NOT NULL, created_by TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, status TEXT NOT NULL, UNIQUE(organization_id, name, version));
CREATE TABLE IF NOT EXISTS risk_cases (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), entity_id TEXT NOT NULL REFERENCES entities(id), domain TEXT NOT NULL, severity TEXT NOT NULL, trajectory TEXT NOT NULL, confidence DOUBLE PRECISION NOT NULL, evidence_coverage DOUBLE PRECISION NOT NULL, status TEXT NOT NULL, owner_id TEXT, reviewer_id TEXT, due_date DATE, rationale TEXT NOT NULL, evidence_ids JSONB NOT NULL, actions JSONB NOT NULL, comments JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events (sequence BIGSERIAL PRIMARY KEY, id TEXT UNIQUE NOT NULL, organization_id TEXT NOT NULL, actor_id TEXT NOT NULL, action TEXT NOT NULL, object_type TEXT NOT NULL, object_id TEXT NOT NULL, payload JSONB NOT NULL, occurred_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS documents (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), entity_id TEXT NOT NULL REFERENCES entities(id), reporting_period TEXT NOT NULL, source_type TEXT NOT NULL, object_key TEXT NOT NULL, sha256 TEXT NOT NULL, accession TEXT, filed_at TIMESTAMPTZ, provenance JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), kind TEXT NOT NULL, idempotency_key TEXT NOT NULL, payload JSONB NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, max_attempts INTEGER NOT NULL DEFAULT 3, error TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, UNIQUE(organization_id, idempotency_key));
CREATE TABLE IF NOT EXISTS model_registry (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), component TEXT NOT NULL, version TEXT NOT NULL, owner_id TEXT NOT NULL, intended_use TEXT NOT NULL, limitations TEXT NOT NULL, validation_status TEXT NOT NULL, dataset_version TEXT, prompt_hash TEXT, rule_version TEXT, fusion_version TEXT, policy_version TEXT, metrics JSONB NOT NULL, last_validation TIMESTAMPTZ, deployment_state TEXT NOT NULL, UNIQUE(organization_id, component, version));
CREATE TABLE IF NOT EXISTS alerts (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), entity_id TEXT NOT NULL REFERENCES entities(id), type TEXT NOT NULL, severity TEXT NOT NULL, payload JSONB NOT NULL, status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS analysis_snapshots (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), entity_id TEXT NOT NULL REFERENCES entities(id), input_hash TEXT NOT NULL, output_hash TEXT NOT NULL, document_versions JSONB NOT NULL, component_versions JSONB NOT NULL, frozen_input JSONB NOT NULL, frozen_output JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS validation_records (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), component TEXT NOT NULL, version TEXT NOT NULL, dataset_version TEXT NOT NULL, status TEXT NOT NULL, metrics JSONB NOT NULL, reviewer_id TEXT, created_at TIMESTAMPTZ NOT NULL);
ALTER TABLE risk_cases ADD COLUMN IF NOT EXISTS reason_codes JSONB NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE risk_cases ADD COLUMN IF NOT EXISTS decision_trace JSONB NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE risk_cases ADD COLUMN IF NOT EXISTS snapshot_id TEXT REFERENCES analysis_snapshots(id);
ALTER TABLE risk_cases ADD COLUMN IF NOT EXISTS fusion_version TEXT;
CREATE INDEX IF NOT EXISTS ix_cases_org_status ON risk_cases(organization_id, status);
CREATE INDEX IF NOT EXISTS ix_audit_org_time ON audit_events(organization_id, occurred_at);
CREATE INDEX IF NOT EXISTS ix_documents_org_entity_period ON documents(organization_id, entity_id, reporting_period);
CREATE INDEX IF NOT EXISTS ix_jobs_org_status ON jobs(organization_id, status);
CREATE INDEX IF NOT EXISTS ix_alerts_org_status ON alerts(organization_id, status);
CREATE INDEX IF NOT EXISTS ix_snapshots_org_entity ON analysis_snapshots(organization_id, entity_id, created_at);
CREATE OR REPLACE FUNCTION reject_audit_mutation() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'audit_events are immutable'; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS audit_events_immutable ON audit_events;
CREATE TRIGGER audit_events_immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION reject_audit_mutation();
